"""v12 docs inside the package: UNITY_CONTRACT.md, README.md, COMPONENTS.md (replacements on the v11 texts + new
section 19). Run after make_package_v12.py (it calls this file at its end).
python3 build_docs12.py <package root>"""
import os, sys

ROOT = sys.argv[1] if len(sys.argv) > 1 else '/home/claude/plane/export/unity_v12/Assets/UtilityPlane'


def patch(name, pairs):
    p = os.path.join(ROOT, name)
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        n = s.count(a)
        assert n == 1, (name, n, a[:90])
        s = s.replace(a, b)
    open(p, 'w', encoding='utf-8').write(s)


# ====================================================================== VRAM estimate (GPU formats on PC: RGBA32 4 B/px,
# DXT1 0.5, DXT5 / BC5 1; mips x 4/3). v11: interior BC DXT1 + Normal 1 B + Mask DXT5, details 512 x 4, gauges 2048 DXT1 x 3,
# webbing; v12: interior colour RGBA32 + mask DXT5, text BC RGBA32 + 2 emission DXT1, webbing RGBA32
def mb(w, h, bpp):
    return w * h * bpp * 4 / 3 / 1048576.0
V11 = 5 * mb(1024, 1024, 2.5) + 2 * mb(512, 512, 0.5) + 2 * mb(512, 512, 1) + 3 * mb(2048, 2048, 0.5) + \
      mb(512, 128, 0.5) + mb(512, 128, 1)
V12 = 4 * mb(1024, 1024, 4) + mb(512, 512, 4) + 4 * mb(1024, 1024, 1) + mb(512, 512, 1) + mb(1024, 1024, 4) + \
      2 * mb(1024, 1024, 0.5) + mb(256, 64, 4)
print('VRAM v11 %.1f MB, v12 %.1f MB' % (V11, V12))

